import { Button, Group, NumberInput, Stack, TextInput } from '@mantine/core';
import { FormErrors, isEmail, isInRange, isNotEmpty, useForm } from '@mantine/form';
import { notifications } from '@mantine/notifications';
import { ExternalControls } from './ExternalControls';
import { DemoFormValues } from './form-actions';

function DemoForm() {
  const form = useForm<DemoFormValues>({
    // Required for createFormActions('demo-form') to reach this form
    name: 'demo-form',
    initialValues: {
      name: '',
      email: '',
      age: '',
    },
    validate: {
      name: isNotEmpty('Name is required'),
      email: isEmail('Invalid email'),
      age: isInRange({ min: 18, max: 120 }, 'Age must be between 18 and 120'),
    },
  });

  const handleSubmit = (values: DemoFormValues) => {
    notifications.show({
      title: 'Form submitted',
      message: `${values.name} (${values.email}), age ${values.age}`,
    });
  };

  const handleErrors = (errors: FormErrors) => {
    form.getInputNode(Object.keys(errors)[0])?.focus();
  };

  return (
    <form onSubmit={form.onSubmit(handleSubmit, handleErrors)}>
      <Stack>
        <TextInput
          size="md"
          label="Name"
          placeholder="Jane Doe"
          withAsterisk
          {...form.getInputProps('name')}
        />

        <TextInput
          size="md"
          label="Email"
          placeholder="jane@mantine.dev"
          withAsterisk
          {...form.getInputProps('email')}
        />

        <NumberInput
          size="md"
          label="Age"
          placeholder="Your age"
          allowNegative={false}
          allowDecimal={false}
          max={120}
          withAsterisk
          {...form.getInputProps('age')}
        />

        <Group justify="flex-end">
          <Button size="md" type="submit">
            Submit
          </Button>
        </Group>
      </Stack>
    </form>
  );
}

export function FormActions() {
  return (
    <Stack>
      <ExternalControls />

      <DemoForm />
    </Stack>
  );
}

import { Button, Group, Surface } from '@mantine/core';
import { demoFormActions } from './form-actions';

export function ExternalControls() {
  return (
    <Surface level={0} withBorder p="md">
      <Group gap="xs">
        <Button
          variant="default"
          onClick={() =>
            demoFormActions.setValues({
              name: 'Jane Doe',
              email: 'jane@mantine.dev',
              age: 32,
            })
          }
        >
          Fill demo data
        </Button>

        <Button
          variant="default"
          onClick={() => demoFormActions.setFieldError('email', 'This email is already taken')}
        >
          Set error
        </Button>

        <Button variant="default" onClick={() => demoFormActions.validate()}>
          Validate
        </Button>

        <Button variant="default" onClick={() => demoFormActions.reset()}>
          Clear
        </Button>
      </Group>
    </Surface>
  );
}

import { createFormActions } from '@mantine/form';

export interface DemoFormValues {
  name: string;
  email: string;
  age: number | string;
}

// Form name must match the `name` option passed to useForm
export const demoFormActions = createFormActions<DemoFormValues>('demo-form');
